// ============================================================================
// FAO HITL Sweeper - Expand Notifications
// ----------------------------------------------------------------------------
// FAO-GOV-004 / FAO-GOV-007: fao_maintenance_sweep has already expired
// overdue requests, written escalation events and decided which
// notifications are due. This node turns its lists into notifier inputs:
//   one {hitl_id, kind: 'ESCALATED', level} per r.escalations entry, and
//   one {hitl_id, kind: 'REQUESTED', level: 0} per r.renotify entry.
// With nothing due it returns no items and this branch ends.
// ============================================================================

const r = (($input.first() || {}).json || {}).r || {};
const escalations = Array.isArray(r.escalations) ? r.escalations : [];
const renotify = Array.isArray(r.renotify) ? r.renotify : [];

const out = [];
for (const e of escalations) {
  out.push({ json: { hitl_id: e.hitl_id, kind: 'ESCALATED', level: e.level } });
}
for (const n of renotify) {
  out.push({ json: { hitl_id: n.hitl_id, kind: 'REQUESTED', level: 0 } });
}

return out;

// ============================================================================
// FAO HITL Sweeper - Check Notifier Results
// ----------------------------------------------------------------------------
// FAO-GOV-007: HITL Gateway calls the notifier once per item with onError
// continueRegularOutput, so one failed call does not stop the others. A
// failed call comes back as an item {error: <message>} paired with its input.
// This node runs after every item has been attempted and lists each failed
// call as hitl_id:kind:level (message). It does not throw: with
// executionOrder v1 this branch runs before Check Sweep Errors, and a throw
// here would end the execution before the sweep's item_errors are read
// (fix round 3). Check Sweep Errors fails the execution once, naming these
// failures and the sweep item errors together. Failures the notifier records
// itself (Slack errors and unusable settings, as NOTIFICATION_FAILED) are
// not errors here; they are retried and escalated by the sweep.
// ============================================================================

const clean = (s) => String(s).replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 120);

let sources = [];
try {
  sources = $('Expand Notifications').all();
} catch (err) {
  sources = [];
}

function pairedIndex(item) {
  const p = item && item.pairedItem;
  const one = Array.isArray(p) ? p[0] : p;
  return one && typeof one === 'object' && Number.isInteger(one.item) ? one.item : null;
}

const results = $input.all();
const failures = [];
for (const item of results) {
  const j = (item && item.json) || {};
  if (j.error === undefined || j.error === null) continue;
  const idx = pairedIndex(item);
  const src = idx !== null && sources[idx] && sources[idx].json ? sources[idx].json : null;
  const label = src ? `${src.hitl_id}:${src.kind}:${src.level}` : 'unknown';
  const msg = typeof j.error === 'string' ? j.error
    : (j.error && typeof j.error === 'object' && typeof j.error.message === 'string' ? j.error.message : 'error');
  failures.push(`${label} (${clean(msg)})`);
}

return [{ json: { notifier_calls: results.length, notifier_failures: failures.length, failures } }];

// ============================================================================
// FAO HITL Sweeper - Check Sweep Errors
// ----------------------------------------------------------------------------
// FAO-GOV-007 / FAO-GOV-008: the one node that fails a sweeper execution, so
// both kinds of failure surface in the same execution.
//   Sweep item errors: each sweep item runs in its own block inside
//   fao_maintenance_sweep, so one bad item does not stop the rest. The items
//   that failed come back in r.item_errors as {step, id, sqlstate}.
//   Notifier call failures: listed by Check Notifier Results.
// Order: with executionOrder v1, Run Sweep's two branches run one after the
// other, topmost on the canvas first. Expand Notifications (with the notifier
// calls and Check Notifier Results under it) sits above this node, so this
// node runs last, on every sweep, after every listed notice was attempted
// (scripts/check-exports.mjs holds the order and the positions).
// Fail closed: when the sweep listed notices (r.escalations, r.renotify) and
// no notifier summary can be read, or it covers fewer calls than were
// listed, that counts as a notifier failure.
// Throws once, naming both: "FAO-GOV-007 sweep: <n> notifier failures: ...;
// FAO-GOV-008 sweep: <n> item errors: ...", each part only when it applies.
// ============================================================================

const r = (($('Run Sweep').first() || {}).json || {}).r || {};
const errors = Array.isArray(r.item_errors) ? r.item_errors : [];
const due = (Array.isArray(r.escalations) ? r.escalations.length : 0)
  + (Array.isArray(r.renotify) ? r.renotify.length : 0);

let summary = null;
if (due > 0) {
  try {
    summary = (($('Check Notifier Results').first() || {}).json) || null;
  } catch (err) {
    summary = null;
  }
}

const notifier = [];
let calls = 0;
if (due > 0) {
  if (!summary || !Number.isInteger(summary.notifier_calls) || !Array.isArray(summary.failures)) {
    notifier.push(`missing (${due} notices listed, no notifier results read)`);
  } else {
    calls = summary.notifier_calls;
    if (calls < due) notifier.push(`missing (${due - calls} of ${due} notices have no notifier result)`);
    for (const f of summary.failures) notifier.push(String(f));
  }
}

const parts = [];
if (notifier.length > 0) {
  parts.push(`FAO-GOV-007 sweep: ${notifier.length} notifier failures: ${notifier.join(', ')}`);
}
if (errors.length > 0) {
  const list = errors.map(e => `${e.step}:${e.id}:${e.sqlstate}`).join(', ');
  parts.push(`FAO-GOV-008 sweep: ${errors.length} item errors: ${list}`);
}
if (parts.length > 0) {
  throw new Error(parts.join('; '));
}

return [{
  json: {
    item_errors: 0,
    notifier_calls: calls,
    notifier_failures: 0,
    grants_drift: r.grants_drift === true,
    clock_offset_seconds: typeof r.clock_offset_seconds === 'number' ? r.clock_offset_seconds : 0
  }
}];
